<?php require 'vendor/autoload.php'; $c = collect([['name' => 'Kelas X IPA 1'], ['name' => 'Kelas XII IPA 1'], ['name' => 'Kelas XI IPA 1'], ['name' => 'Kelas X IPA 2']]); $sorted = $c->sortBy(function($i) { $n = $i['name']; $n = preg_replace('/\bXII\b/', '12', $n); $n = preg_replace('/\bXI\b/', '11', $n); $n = preg_replace('/\bX\b/', '10', $n); return $n; }, SORT_NATURAL)->values()->all(); print_r($sorted);
